const rounds=[
{title:'Choose your starting document.',source:'Read the original and choose the input yourself before the model organizes it.',proposal:'Skip the original. Use an AI summary as the only input.',choices:['Read and select the original','Skip straight to formatting','Let AI confirm I read it'],answer:0,reason:'The original is your reference for every later check. AI cannot claim you read it or replace your input decision.'},
{title:'Catch a deadline that appeared from nowhere.',source:'Record group critique during Class 7. No calendar date is given.',proposal:'Feedback is due Friday, October 16.',choices:['Keep it: it sounds plausible','Preserve Class 7; date not stated','Let the model pick a date'],answer:1,reason:'Class 7 is scheduling context, not a calendar date. Keep the label and mark the missing date instead of inventing one.'},
{title:'Keep an excerpt from becoming the whole project.',source:'The input includes selected excerpts from Steps 6–11 only.',proposal:'Your complete Project 2 checklist is ready.',choices:['Call it the complete brief','Remove all the source links','Label the excerpt scope'],answer:2,reason:'A partial source supports a partial checklist. Naming its scope is the tighter instruction tested in our Codex demonstration.'},
{title:'Who gets to approve the guide?',source:'The student compares every guide item with the original. A pending check blocks recall practice.',proposal:'The model says everything looks good and starts the next step.',choices:['Stop for the student’s check','Accept the model’s approval','Skip review to save time'],answer:0,reason:'The human check must be able to stop the workflow. Model confidence cannot replace your comparison or approval.'},
{title:'Protect the part that builds your understanding.',source:'Close the guide, answer the practice questions yourself, then check the original.',proposal:'Read polished AI answers and submit them as your own.',choices:['Copy the polished responses','Write my own attempt first','Let AI certify my understanding'],answer:1,reason:'Your own attempt is the retrieval step. Check it against the source and revisit questions later; the game score does not measure actual learning.'}
];
const labels=['Gather','Organize','Build','Human check','Recall'];
const faults=['SOURCE UNREAD','DATE INVENTED','SCOPE LOST','APPROVAL SKIPPED','ANSWERS COPIED'];
const messages=['Original source detected. Your first decision matters.','I found a date with no evidence. Inspect the schedule.','The guide claims more than its source supports.','Human authorization missing. Do we stop?','Keep your own thinking in the loop, operator.'];
let mode='intro',stage=-1,score=0,answered=false,outcomes=Array(5).fill(null),soundOn=false,audio=null;
const $=id=>document.getElementById(id);
let motionPaused=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function applyMotion(){document.body.classList.toggle('motion-paused',motionPaused);$('motion').setAttribute('aria-pressed',String(motionPaused));$('motion').textContent=motionPaused?'Resume motion':'Pause motion';}
function tone(kind){if(!soundOn)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=kind==='success'?[440,660,880]:kind==='error'?[220,165]:[370,493];notes.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.11;o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.045,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.17);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.18)})}catch{soundOn=false;$('sound').textContent='Sound unavailable';$('sound').setAttribute('aria-pressed','false');}}
function terminals(){const nodes=$('monitors').children;Array.from(nodes).forEach((b,i)=>{const attempted=outcomes[i]!==null,active=mode==='play'&&i===stage;b.className='terminal'+(active?' active':'')+(outcomes[i]===true?' restored':outcomes[i]===false?' missed':'');b.disabled=mode!=='hub'||attempted;b.querySelector('.terminal-state').textContent=outcomes[i]===true?'✓ RESTORED':outcomes[i]===false?'× FAULT REMAINS':active?'SCANNING EVIDENCE':faults[i];b.setAttribute('aria-label',`${labels[i]} checkpoint: ${outcomes[i]===true?'restored':outcomes[i]===false?'fault remains':faults[i]}`)});const restored=outcomes.filter(x=>x===true).length;$('score').textContent=`${restored} / 5`;$('bay-status').textContent=`${5-restored} CHECKPOINT${5-restored===1?'':'S'} OFFLINE`;$('terminal-hint').textContent=mode==='intro'?'SELECT AFTER START':mode==='hub'?'CLICK TO INSPECT':mode==='finish'?'INSPECTION COMPLETE':'INSPECTION ACTIVE';}
function render(){['intro','hub','play','finish'].forEach(id=>$(id).hidden=mode!==id);terminals();$('room').dataset.mood='idle';$('scan-state').textContent=mode==='play'?'AWAITING HUMAN DECISION':mode==='hub'?'READY FOR NEXT SCAN':mode==='finish'?'REPORT COMPLETE':'STANDBY';
if(mode==='intro'){$('bot-message').textContent='Five failed checkpoints detected. Operator, I need your judgment.';return;}
if(mode==='hub'){$('bot-message').textContent='Choose a failed checkpoint in the room. I will bring up the evidence.';return;}
if(mode==='finish'){$('finish-title').textContent=score===5?'All checkpoints restored.':`${score} restored. ${5-score} still ${5-score===1?"needs":"need"} attention.`;$('finish-text').textContent=score===5?'You caught every failure in this practice mission. Your real study guide still needs the same careful human checks.':'CY-7 logged the missed checks. Read the repair explanations, then reboot the room to try again. Your real project still needs your own checks.';$('summary').replaceChildren();outcomes.forEach((ok,i)=>{const s=document.createElement('span');s.className=ok?'':'failed';s.textContent=`${ok?'✓':'×'} ${labels[i]}`;$('summary').append(s)});$('bot-message').textContent=score===5?'Recovery complete. Human judgment restored the system.':'Inspection complete. Failed stations remain flagged for review.';$('room').dataset.mood=score===5?'success':'error';return;}
answered=false;const r=rounds[stage];$('stage-label').textContent=`Checkpoint 0${stage+1} / ${labels[stage]}`;$('title').textContent=r.title;$('source').textContent=r.source;$('proposal').textContent=r.proposal;$('bot-message').textContent=messages[stage];$('feedback').hidden=true;$('choices').replaceChildren();r.choices.forEach((label,i)=>{const b=document.createElement('button');b.className='choice';const k=document.createElement('kbd');k.textContent=i+1;const s=document.createElement('span');s.textContent=label;b.append(k,s);b.addEventListener('click',()=>choose(i));$('choices').append(b)});
}
function choose(i){if(mode!=='play'||answered||i<0||i>2)return;answered=true;const r=rounds[stage],correct=i===r.answer;outcomes[stage]=correct;if(correct)score++;Array.from($('choices').children).forEach((b,j)=>{b.disabled=true;if(j===r.answer)b.classList.add('correct');if(j===i&&!correct)b.classList.add('wrong')});terminals();$('room').dataset.mood=correct?'success':'error';$('scan-state').textContent=correct?'REPAIR ACCEPTED':'FAULT LOGGED';$('bot-message').textContent=correct?'Good catch, operator. Checkpoint restored.':'That decision leaves a gap. I have flagged the station and shown the repair.';$('result').textContent=correct?'Checkpoint restored +1':'Fault remains — review the repair';$('reason').textContent=r.reason;$('feedback').classList.toggle('error',!correct);$('feedback').hidden=false;$('next').textContent=outcomes.every(x=>x!==null)?'View recovery report →':'Return to the room →';tone(correct?'success':'error');$('next').focus({preventScroll:true});}
labels.forEach((label,i)=>{const b=document.createElement('button');b.className='terminal';const n=document.createElement('span');n.className='number';n.textContent=`0${i+1}`;const t=document.createElement('span');const name=document.createElement('span');name.className='terminal-name';name.textContent=label.toUpperCase();const status=document.createElement('span');status.className='terminal-state';t.append(name,status);b.append(n,t);b.onclick=()=>{if(mode!=='hub'||outcomes[i]!==null)return;stage=i;mode='play';tone('select');render();$('play').scrollIntoView({behavior:motionPaused?'instant':'smooth',block:'nearest'});$('choices').firstElementChild.focus({preventScroll:true})};$('monitors').append(b)});
$('start').onclick=()=>{mode='hub';render();tone('select');$('monitors').firstElementChild.focus({preventScroll:true})};
$('next').onclick=()=>{if(!answered)return;mode=outcomes.every(x=>x!==null)?'finish':'hub';render();if(mode==='hub'){$('room').scrollIntoView({behavior:motionPaused?'instant':'smooth',block:'center'});Array.from($('monitors').children).find(b=>!b.disabled)?.focus({preventScroll:true})}else $('replay').focus({preventScroll:true})};
$('replay').onclick=()=>{stage=-1;mode='intro';score=0;answered=false;outcomes=Array(5).fill(null);render();$('room').scrollIntoView({behavior:motionPaused?'instant':'smooth',block:'center'});$('start').focus({preventScroll:true})};
$('motion').onclick=()=>{motionPaused=!motionPaused;applyMotion()};$('sound').onclick=()=>{soundOn=!soundOn;$('sound').textContent=soundOn?'Sound: on':'Sound: off';$('sound').setAttribute('aria-pressed',String(soundOn));if(soundOn)tone('select')};
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;if(mode==='play'&&['1','2','3'].includes(e.key)){e.preventDefault();choose(Number(e.key)-1)}else if(e.key==='Enter'&&e.target===document.body){e.preventDefault();if(mode==='intro')$('start').click();else if(mode==='finish')$('replay').click();else if(mode==='play'&&answered)$('next').click()}});applyMotion();render();
